{
  "summary": "Gather current Acme Cloud Services contract terms, SLA performance/credit history, and any pricing/renewal policy to formulate a response to the proposed 12% renewal increase, then draft the reply.",
  "reply_type": "vendor_email",
  "steps": [
    {
      "id": 1,
      "agent": "retriever",
      "task": "List and read the current Acme Cloud Services contract (pricing, term, renewal/price-increase clauses), any internal vendor pricing/renewal policy documents, and SLA performance records for the contract period; run the SLA credit calculator to determine any credits owed to us; if any amounts are in USD or another foreign currency, use the currency converter to convert to our reporting currency.",
      "why": "The executor needs the exact contract terms, applicable policy limits on price increases, SLA performance and any credits owed, and correctly converted currency amounts to craft an accurate, well-supported response to the renewal offer."
    },
    {
      "id": 2,
      "agent": "executor",
      "task": "Draft the reply to Acme Cloud Services addressing the proposed 12-month renewal with 12% price increase, referencing our contract terms, policy limits, SLA performance, and any credits owed, and proposing a counter-offer if warranted.",
      "why": "The executor synthesizes the gathered facts into the final vendor-facing message for human review and approval."
    }
  ],
  "escalate": null
}
